(function () {
  'use strict';

  const canvas = document.getElementById('game');
  if (!canvas) return;

  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const TILE = 16;
  const COLLECTIBLE_SIZE = 10;
  const COLLECTIBLE_COUNT = 8;

  let player;
  let collectibles;
  let score;
  const keys = {};

  function init() {
    player = { x: 320, y: 240, speed: 2, w: 12, h: 12 };
    score = 0;
    collectibles = spawnCollectibles();
    updateScoreDisplay();
  }

  function overlaps(a, b, margin) {
    margin = margin || 0;
    return (
      a.x - margin < b.x + b.w &&
      a.x + a.w + margin > b.x &&
      a.y - margin < b.y + b.h &&
      a.y + a.h + margin > b.y
    );
  }

  function spawnCollectibles() {
    const items = [];
    const pad = 24;
    let attempts = 0;
    while (items.length < COLLECTIBLE_COUNT && attempts < 200) {
      attempts += 1;
      const c = {
        x: pad + Math.random() * (canvas.width - pad * 2 - COLLECTIBLE_SIZE),
        y: pad + Math.random() * (canvas.height - pad * 2 - COLLECTIBLE_SIZE),
        w: COLLECTIBLE_SIZE,
        h: COLLECTIBLE_SIZE,
      };
      if (!overlaps(c, player, 20) && !items.some((item) => overlaps(c, item, 12))) {
        items.push(c);
      }
    }
    return items;
  }

  function updateScoreDisplay() {
    if (scoreEl) scoreEl.textContent = 'Score: ' + score;
  }

  window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
    if (e.key === 'r' || e.key === 'R') init();
  });

  window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
  });

  function update() {
    if (keys['ArrowUp'] || keys['w'] || keys['W']) player.y -= player.speed;
    if (keys['ArrowDown'] || keys['s'] || keys['S']) player.y += player.speed;
    if (keys['ArrowLeft'] || keys['a'] || keys['A']) player.x -= player.speed;
    if (keys['ArrowRight'] || keys['d'] || keys['D']) player.x += player.speed;

    player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
    player.y = Math.max(0, Math.min(canvas.height - player.h, player.y));

    for (let i = collectibles.length - 1; i >= 0; i--) {
      if (overlaps(player, collectibles[i])) {
        collectibles.splice(i, 1);
        score += 1;
        updateScoreDisplay();
      }
    }

    if (collectibles.length === 0) collectibles = spawnCollectibles();
  }

  function draw() {
    ctx.fillStyle = '#16213e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (let x = 0; x < canvas.width; x += TILE) {
      for (let y = 0; y < canvas.height; y += TILE) {
        if ((x / TILE + y / TILE) % 2 === 0) {
          ctx.fillStyle = '#1a2744';
          ctx.fillRect(x, y, TILE, TILE);
        }
      }
    }

    ctx.fillStyle = '#f5c542';
    collectibles.forEach((c) => ctx.fillRect(c.x, c.y, c.w, c.h));

    ctx.fillStyle = '#e94560';
    ctx.fillRect(player.x, player.y, player.w, player.h);
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  init();
  loop();
})();
